fn vec_min_i8(arr: &Vec<i8>) -> i8 {
    *arr.iter().min().unwrap() // Find the minimum value in the array
}

fn vec_max_i8(arr: &Vec<i8>) -> i8 {
    *arr.iter().max().unwrap() // Find the maximum value in the array
}

fn percentile(arr: Vec<i8>, q: i8) -> i8 {
    if q == 0 {
        vec_min_i8(&arr) // Return the minimum for q = 0
    } else if q == 100 {
        vec_max_i8(&arr) // Return the maximum for q = 100
    } else {
        // For other values of q, we can return any element from the array
        // that satisfies the conditions. We can simply return the first element.
        arr[0]
    }
}

fn main() {
    let arr = vec![3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5];
    let q0 = percentile(arr.clone(), 0);
    let q100 = percentile(arr.clone(), 100);
    let q50 = percentile(arr.clone(), 50);

    println!("Percentile 0: {}", q0);   // Should print the minimum
    println!("Percentile 100: {}", q100); // Should print the maximum
    println!("Percentile 50: {}", q50);  // Should print any element from the array
}